INSERT INTO `wp_latepoint_processes` VALUES (1,'New Booking Notification','booking_created','[{\"type\":\"group\",\"trigger_condition\":false,\"items\":[{\"type\":\"action\",\"id\":\"pa_T97vRF\",\"settings\":{\"status\":\"active\",\"type\":\"send_email\",\"settings\":{\"to_email\":\"{{agent_full_name}} <{{agent_email}}>\",\"subject\":\"New Appointment Received\",\"content\":\"<div style=\\\"padding: 20px; background-color: #f0f0f0; font-family: -apple-system, system-ui, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, \\\"Helvetica Neue\\\", Arial, sans-serif;\\\">\\n\\t<div style=\\\"background-color: #fff; padding: 30px; margin: 0px auto; max-width: 450px; box-shadow: 0px 2px 6px -1px rgba(0,0,0,0.2); border-radius: 6px;\\\">\\n\\t\\t<div style=\\\"margin: 0px auto 30px auto; border-bottom: 1px solid #eee; padding-bottom: 20px;\\\">\\n\\t\\t\\t<table style=\\\"width: 100%;\\\">\\n\\t\\t\\t\\t<tr>\\n\\t\\t\\t\\t\\t<td>{{business_logo_image}}<\\/td>\\n\\t\\t\\t\\t\\t<td style=\\\"text-align: right;\\\"><span style=\\\"color: #7b7b7b;\\\">Questions?<\\/span><br\\/><strong>{{business_phone}}<\\/strong><\\/td>\\n\\t\\t\\t\\t<\\/tr>\\n\\t\\t\\t<\\/table>\\n\\t\\t<\\/div>\\n\\t\\t<div style=\\\"font-size: 16px; line-height: 1.5;\\\">\\n\\t\\t\\t<div style=\\\"font-size: 16px; margin-bottom: 20px; line-height: 1.6;\\\">\\n\\tHi {{agent_full_name}},\\n\\t<br\\/><br\\/>\\n\\tYou have received a new appointment request from {{customer_full_name}}\\n<\\/div>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Customer Information<\\/h4>\\n<ul>\\n\\t<li>\\n\\t\\t<span>Full Name:<\\/span> <strong>{{customer_full_name}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Email Address:<\\/span> <strong>{{customer_email}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Phone:<\\/span> <strong>{{customer_phone}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Comments:<\\/span> <strong>{{customer_notes}}<\\/strong>\\n\\t<\\/li>\\n<\\/ul>\\n<h4 st